-- JewelVault schema for MariaDB 11.8. GENERATED by scripts/build-schema.mjs from db/migrations; do not edit by hand.
-- Paste into phpMyAdmin (SQL tab) of an EMPTY database. Re-running it is safe. The migration runner (npm run db:migrate) is the normal way.
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
SET SESSION time_zone = '+00:00';

-- ==== 0001_system ====
-- 0001 system tables: number counters, repeat-safety, import batches, job runs, error log, login throttle (spec D18, L3, L5, I8; NODE-DESIGN D-Q1).
-- Names start with sys_ so they are never mixed up with business tables. Only the API touches them.
-- Conventions of this schema (checked by tests/schema/s2-catalogue.test.ts):
--   InnoDB, utf8mb4_unicode_ci (case-insensitive unique keys); ids are native UUID; money DECIMAL(14,2), rates DECIMAL(12,2), weights DECIMAL(12,3);
--   timestamps DATETIME(6) in UTC; every foreign key is RESTRICT; no UNIQUE index on a column that changes after insert (spike finding F2);
--   no name needs quoting (key, lines, rows, order ... are reserved words in MariaDB); person columns (created_by ...) are plain UUIDs, no foreign key.

CREATE TABLE IF NOT EXISTS sys_counters (
  series VARCHAR(60) NOT NULL,
  last_value BIGINT NOT NULL DEFAULT 0,
  seed_value BIGINT NOT NULL DEFAULT 0,
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (series),
  CONSTRAINT chk_counters_values CHECK (seed_value >= 0 AND last_value >= seed_value)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_idempotency (
  request_id UUID NOT NULL,
  fn VARCHAR(40) NOT NULL,
  actor UUID NOT NULL,
  args_hash CHAR(64) NOT NULL,
  claim_token UUID NULL,
  result JSON NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (request_id),
  KEY ix_idempotency_created (created_at),
  CONSTRAINT chk_idempotency_hash CHECK (CHAR_LENGTH(args_hash) = 64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_import_batches (
  id UUID NOT NULL,
  name VARCHAR(120) NOT NULL,
  source_file VARCHAR(255) NULL,
  row_counts JSON NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_import_batches_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_job_runs (
  id BIGINT NOT NULL AUTO_INCREMENT,
  job VARCHAR(40) NOT NULL,
  run_date DATE NOT NULL,
  status VARCHAR(12) NOT NULL DEFAULT 'running',
  started_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  finished_at DATETIME(6) NULL,
  detail JSON NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_job_runs_day (job, run_date),
  CONSTRAINT chk_job_runs_status CHECK (status IN ('running', 'ok', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_error_log (
  id BIGINT NOT NULL AUTO_INCREMENT,
  at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  level VARCHAR(10) NOT NULL,
  code VARCHAR(40) NOT NULL,
  message VARCHAR(500) NOT NULL,
  request_id UUID NULL,
  user_id UUID NULL,
  detail JSON NULL,
  PRIMARY KEY (id),
  KEY ix_error_log_at (at),
  CONSTRAINT chk_error_log_level CHECK (level IN ('debug', 'info', 'warn', 'error', 'fatal'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sys_login_attempts (
  id BIGINT NOT NULL AUTO_INCREMENT,
  email_hash VARBINARY(32) NOT NULL,
  ip_hash VARBINARY(32) NOT NULL,
  at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_login_attempts_email (email_hash, at),
  KEY ix_login_attempts_ip (ip_hash, at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0002_users_sessions ====
-- 0002 users and sessions (replace spec D1 profiles on auth.users; NODE-DESIGN 2.3).
-- The role lives here and nowhere else. A new user is inactive until activated. The password is stored only as a hash.

CREATE TABLE IF NOT EXISTS users (
  id UUID NOT NULL,
  email VARCHAR(254) NOT NULL,
  full_name VARCHAR(120) NOT NULL,
  role VARCHAR(12) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 0,
  password_hash VARCHAR(255) NOT NULL,
  must_change_password TINYINT(1) NOT NULL DEFAULT 0,
  last_login_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY ix_users_updated (updated_at, id),
  CONSTRAINT chk_users_role CHECK (role IN ('owner', 'biller', 'staff')),
  CONSTRAINT chk_users_email CHECK (LOCATE('@', email) > 1),
  CONSTRAINT chk_users_name CHECK (CHAR_LENGTH(TRIM(full_name)) >= 1),
  CONSTRAINT chk_users_flags CHECK (active IN (0, 1) AND must_change_password IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sessions (
  id UUID NOT NULL,
  user_id UUID NOT NULL,
  token_hash VARBINARY(32) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  last_seen_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  expires_at DATETIME(6) NOT NULL,
  revoked_at DATETIME(6) NULL,
  user_agent VARCHAR(200) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sessions_token (token_hash),
  KEY ix_sessions_user (user_id),
  KEY ix_sessions_expires (expires_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_sessions_token CHECK (OCTET_LENGTH(token_hash) = 32)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0003_settings_rates_catalog ====
-- 0003 settings, daily rates, categories (spec D3, D4, D5).
-- The seeds (D20) live in db/seeds; this file only makes the tables.

CREATE TABLE IF NOT EXISTS settings (
  setting_key VARCHAR(64) NOT NULL,
  value JSON NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (setting_key),
  KEY ix_settings_updated (updated_at, setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS daily_rates (
  id UUID NOT NULL,
  material VARCHAR(10) NOT NULL,
  purity VARCHAR(20) NOT NULL,
  rate_per_gram DECIMAL(12,2) NOT NULL,
  rate_date DATE NOT NULL,
  confirmed_by UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_daily_rates_day (rate_date, material, purity),
  KEY ix_daily_rates_updated (updated_at, id),
  CONSTRAINT chk_daily_rates_material CHECK (material IN ('Gold', 'Silver')),
  CONSTRAINT chk_daily_rates_rate CHECK (rate_per_gram > 0 AND rate_per_gram <= 100000000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (
  id UUID NOT NULL,
  name VARCHAR(80) NOT NULL,
  prefix VARCHAR(12) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_categories_name (name),
  KEY ix_categories_updated (updated_at, id),
  CONSTRAINT chk_categories_name CHECK (CHAR_LENGTH(TRIM(name)) >= 1),
  CONSTRAINT chk_categories_prefix CHECK (BINARY prefix REGEXP '^[A-Z0-9]{2,6}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS subcategories (
  id UUID NOT NULL,
  category_id UUID NOT NULL,
  name VARCHAR(80) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_subcategories_name (category_id, name),
  KEY ix_subcategories_updated (updated_at, id),
  CONSTRAINT fk_subcategories_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_subcategories_name CHECK (CHAR_LENGTH(TRIM(name)) >= 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0004_customers ====
-- 0004 customers (spec D10, K5).
-- One walk-in row: a generated column that is 1 only for the walk-in, with a UNIQUE key on it (MariaDB has no partial index; is_walkin never changes, so this key is safe, spike F2).
-- mobile: ten digits, or + and 7 to 15 digits; blank only for an imported customer (import_batch_id set) and for the walk-in (O33).
-- PAN: five capital letters, four digits, one capital letter. BINARY is needed: a plain REGEXP is case-insensitive on this collation (tested).

CREATE TABLE IF NOT EXISTS customers (
  id UUID NOT NULL,
  name VARCHAR(120) NOT NULL,
  mobile VARCHAR(20) NULL,
  customer_type VARCHAR(16) NOT NULL DEFAULT 'Retail',
  email VARCHAR(254) NULL,
  address VARCHAR(500) NULL,
  gst_number VARCHAR(20) NULL,
  pan VARCHAR(10) NULL,
  notes TEXT NULL,
  is_walkin TINYINT(1) NOT NULL DEFAULT 0,
  walkin_key TINYINT AS (IF(is_walkin = 1, 1, NULL)) PERSISTENT,
  archived_at DATETIME(6) NULL,
  import_batch_id UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_customers_walkin (walkin_key),
  KEY ix_customers_mobile (mobile),
  KEY ix_customers_import (import_batch_id),
  KEY ix_customers_updated (updated_at, id),
  CONSTRAINT fk_customers_import FOREIGN KEY (import_batch_id) REFERENCES sys_import_batches (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_customers_name CHECK (CHAR_LENGTH(TRIM(name)) >= 1),
  CONSTRAINT chk_customers_type CHECK (customer_type IN ('Retail', 'Semi-Wholesale', 'Wholesale')),
  CONSTRAINT chk_customers_mobile CHECK (mobile IS NULL OR mobile REGEXP '^([0-9]{10}|[+][0-9]{7,15})$'),
  CONSTRAINT chk_customers_mobile_required CHECK (mobile IS NOT NULL OR import_batch_id IS NOT NULL OR is_walkin = 1),
  CONSTRAINT chk_customers_pan CHECK (pan IS NULL OR BINARY pan REGEXP '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  CONSTRAINT chk_customers_walkin CHECK (is_walkin IN (0, 1) AND (is_walkin = 0 OR (pan IS NULL AND archived_at IS NULL)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0005_designs_photos ====
-- 0005 designs and photos (spec draft 4: D6, D26, P1 to P7; photos live in MariaDB, Harsh 15 Oct 2026; copy tracking from NODE-DESIGN D-Q11).
-- designs keeps only photo ids (an ordered JSON array, at most 3, the first is the primary one). The bytes are in design_photos; no list query may ever select them.
-- A photo is two rows with the same id: kind 'full' (longest side 1000 px, JPEG quality 72) and kind 'thumb' (320 px). Rules in settings key 'photos'.
-- design_photos.design_id has NO foreign key: the screen uploads before the design exists (P2); the monthly sweep (P6) finds photos no design refers to.
-- Rows are insert-only. Removing a photo is a tombstone UPDATE (removed_at set, bytes emptied): S7, nothing is deleted. Each photo is copied once to the off-site bucket (sys_photo_copies).

CREATE TABLE IF NOT EXISTS designs (
  id UUID NOT NULL,
  design_no VARCHAR(64) NOT NULL,
  name VARCHAR(120) NULL,
  category_id UUID NOT NULL,
  subcategory_id UUID NULL,
  material VARCHAR(10) NOT NULL,
  purity VARCHAR(20) NOT NULL,
  selling_method VARCHAR(16) NOT NULL,
  description TEXT NULL,
  notes TEXT NULL,
  tags JSON NOT NULL DEFAULT '[]',
  primary_photo_id UUID NULL,
  photo_ids JSON NOT NULL DEFAULT '[]',
  archived_at DATETIME(6) NULL,
  import_batch_id UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_designs_no (design_no),
  KEY ix_designs_category (category_id),
  KEY ix_designs_subcategory (subcategory_id),
  KEY ix_designs_import (import_batch_id),
  KEY ix_designs_updated (updated_at, id),
  CONSTRAINT fk_designs_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_designs_subcategory FOREIGN KEY (subcategory_id) REFERENCES subcategories (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_designs_import FOREIGN KEY (import_batch_id) REFERENCES sys_import_batches (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_designs_no CHECK (CHAR_LENGTH(TRIM(design_no)) >= 1),
  CONSTRAINT chk_designs_material CHECK (material IN ('Gold', 'Silver')),
  CONSTRAINT chk_designs_method CHECK (selling_method IN ('By Weight', 'Per Piece')),
  CONSTRAINT chk_designs_tags CHECK (JSON_TYPE(tags) = 'ARRAY'),
  CONSTRAINT chk_designs_photos CHECK (JSON_TYPE(photo_ids) = 'ARRAY' AND JSON_LENGTH(photo_ids) <= 3 AND JSON_SEARCH(photo_ids, 'one', 'data:%') IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS design_photos (
  id UUID NOT NULL,
  kind VARCHAR(10) NOT NULL,
  design_id UUID NOT NULL,
  mime VARCHAR(20) NOT NULL,
  byte_size INT NOT NULL,
  sha256 VARBINARY(32) NOT NULL,
  bytes MEDIUMBLOB NULL,
  removed_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  PRIMARY KEY (id, kind),
  KEY ix_design_photos_design (design_id),
  CONSTRAINT chk_design_photos_kind CHECK (kind IN ('full', 'thumb')),
  CONSTRAINT chk_design_photos_mime CHECK (mime IN ('image/jpeg', 'image/png', 'image/webp')),
  CONSTRAINT chk_design_photos_size CHECK (byte_size >= 1 AND byte_size <= 2097152),
  CONSTRAINT chk_design_photos_hash CHECK (OCTET_LENGTH(sha256) = 32),
  CONSTRAINT chk_design_photos_state CHECK (
    (removed_at IS NULL AND bytes IS NOT NULL AND byte_size = OCTET_LENGTH(bytes)) OR (removed_at IS NOT NULL AND bytes IS NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per photo copy made to the off-site bucket (D-Q11). The nightly export leaves the bytes out; a photo never changes, so one copy is enough.
-- The job copies the live photos that have no row here, oldest first, then inserts the row. The restore tool reads this table to know what to fetch.
CREATE TABLE IF NOT EXISTS sys_photo_copies (
  photo_id UUID NOT NULL,
  kind VARCHAR(10) NOT NULL,
  sha256 VARBINARY(32) NOT NULL,
  object_key VARCHAR(200) NOT NULL,
  copied_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (photo_id, kind),
  CONSTRAINT fk_photo_copies_photo FOREIGN KEY (photo_id, kind) REFERENCES design_photos (id, kind) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_photo_copies_hash CHECK (OCTET_LENGTH(sha256) = 32)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0006_bills ====
-- 0006 bills (spec D11, R8, K1, K6). Bills are never edited; a correction is a cancel plus a re-issue (reissue_of).
-- No API call updates a bill except cancel (status, cancel_*) and the touch of updated_at. All amounts are exact DECIMAL.
-- (id, customer_id) is UNIQUE so that receipt_allocations can use a composite foreign key and never join another customer's bill (Y4).

CREATE TABLE IF NOT EXISTS bills (
  id UUID NOT NULL,
  bill_no VARCHAR(30) NOT NULL,
  customer_id UUID NOT NULL,
  bill_date DATE NOT NULL,
  doc_type VARCHAR(16) NOT NULL DEFAULT 'estimate',
  sale_type VARCHAR(16) NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  cancel_reason VARCHAR(500) NULL,
  cancelled_at DATETIME(6) NULL,
  cancelled_by UUID NULL,
  reissue_of UUID NULL,
  pricing_version SMALLINT NOT NULL DEFAULT 1,
  subtotal DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  discount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  additional_charges DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  gst_percent DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  gst_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  grand_total DECIMAL(14,2) NOT NULL,
  round_off DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  fine_weight_due DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  notes TEXT NULL,
  cash_override_reason VARCHAR(500) NULL,
  import_batch_id UUID NULL,
  request_id UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_bills_no (bill_no),
  UNIQUE KEY uq_bills_request (request_id),
  UNIQUE KEY uq_bills_reissue (reissue_of),
  UNIQUE KEY uq_bills_id_customer (id, customer_id),
  KEY ix_bills_customer_date (customer_id, bill_date),
  KEY ix_bills_import (import_batch_id),
  KEY ix_bills_updated (updated_at, id),
  CONSTRAINT fk_bills_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bills_reissue FOREIGN KEY (reissue_of) REFERENCES bills (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bills_import FOREIGN KEY (import_batch_id) REFERENCES sys_import_batches (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_bills_doc_type CHECK (doc_type IN ('estimate', 'tax_invoice', 'bill_of_supply', 'opening_balance')),
  CONSTRAINT chk_bills_sale_type CHECK (sale_type IN ('Retail', 'Semi-Wholesale', 'Wholesale')),
  CONSTRAINT chk_bills_status CHECK (status IN ('active', 'cancelled')),
  CONSTRAINT chk_bills_cancel CHECK (
    ((status = 'cancelled') = (cancel_reason IS NOT NULL)) AND ((status = 'cancelled') = (cancelled_at IS NOT NULL)) AND ((status = 'cancelled') = (cancelled_by IS NOT NULL))
  ),
  CONSTRAINT chk_bills_amounts CHECK (
    subtotal >= 0 AND subtotal <= 1000000000 AND discount >= 0 AND discount <= 1000000000 AND additional_charges >= 0 AND additional_charges <= 1000000000
    AND gst_amount >= 0 AND gst_amount <= 1000000000 AND grand_total >= 0 AND grand_total <= 1000000000
  ),
  CONSTRAINT chk_bills_round_off CHECK (round_off >= -0.50 AND round_off <= 0.50),
  CONSTRAINT chk_bills_gst CHECK (gst_percent >= 0 AND gst_percent <= 100),
  CONSTRAINT chk_bills_fine CHECK (fine_weight_due >= 0 AND fine_weight_due <= 20000000),
  CONSTRAINT chk_bills_version CHECK (pricing_version >= 1),
  CONSTRAINT chk_bills_whole_rupee CHECK (doc_type <> 'estimate' OR grand_total = ROUND(grand_total, 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0007_skus ====
-- 0007 pieces and the owner-only weight (spec D7, D8, D9).
-- Rules NOT in the database on purpose: "net weight not above gross weight" and "net weight above 0 for a By Weight design" (O37: they run only on insert and when a weight changes,
-- never on a status change, and the second needs the design); "selling_method cannot change while the design has pieces" (needs the design). They are rules of the API.
-- sold_bill_id is indexed by its foreign key, so "the pieces of this bill" is never a table scan. There is deliberately NO unique key on it (spike finding F2):
-- "no piece on two active bills" is invariant I2, protected by the piece row lock of K2.

CREATE TABLE IF NOT EXISTS skus (
  id UUID NOT NULL,
  design_id UUID NOT NULL,
  sku_no VARCHAR(64) NOT NULL,
  barcode VARCHAR(64) NOT NULL,
  gross_weight DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  customer_net_weight DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  stones INT NOT NULL DEFAULT 0,
  stone_weight DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  kundan INT NOT NULL DEFAULT 0,
  kundan_weight DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  piroi DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  labour_retail DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  labour_semi DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  labour_wholesale DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  status VARCHAR(12) NOT NULL DEFAULT 'In Stock',
  location VARCHAR(60) NULL,
  notes TEXT NULL,
  sold_bill_id UUID NULL,
  archived_at DATETIME(6) NULL,
  import_batch_id UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_skus_no (sku_no),
  UNIQUE KEY uq_skus_barcode (barcode),
  KEY ix_skus_design (design_id),
  KEY ix_skus_status (status),
  KEY ix_skus_sold_bill (sold_bill_id),
  KEY ix_skus_import (import_batch_id),
  KEY ix_skus_updated (updated_at, id),
  CONSTRAINT fk_skus_design FOREIGN KEY (design_id) REFERENCES designs (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_skus_sold_bill FOREIGN KEY (sold_bill_id) REFERENCES bills (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_skus_import FOREIGN KEY (import_batch_id) REFERENCES sys_import_batches (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_skus_status CHECK (status IN ('In Stock', 'Reserved', 'On Approval', 'Sold', 'Returned', 'Repair', 'Transferred', 'Missing', 'Damaged', 'Archived')),
  CONSTRAINT chk_skus_sold CHECK ((status = 'Sold') = (sold_bill_id IS NOT NULL)),
  CONSTRAINT chk_skus_archived CHECK ((status = 'Archived') = (archived_at IS NOT NULL)),
  CONSTRAINT chk_skus_weights CHECK (
    gross_weight >= 0 AND gross_weight <= 100000 AND customer_net_weight >= 0 AND customer_net_weight <= 100000
    AND stone_weight >= 0 AND stone_weight <= 100000 AND kundan_weight >= 0 AND kundan_weight <= 100000
  ),
  CONSTRAINT chk_skus_rates CHECK (
    labour_retail >= 0 AND labour_retail <= 100000000 AND labour_semi >= 0 AND labour_semi <= 100000000 AND labour_wholesale >= 0 AND labour_wholesale <= 100000000
  ),
  CONSTRAINT chk_skus_piroi CHECK (piroi >= 0 AND piroi <= 1000000000),
  CONSTRAINT chk_skus_counts CHECK (stones >= 0 AND kundan >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sku_private (
  sku_id UUID NOT NULL,
  original_net_weight DECIMAL(12,3) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (sku_id),
  KEY ix_sku_private_updated (updated_at, sku_id),
  CONSTRAINT fk_sku_private_sku FOREIGN KEY (sku_id) REFERENCES skus (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_sku_private_weight CHECK (original_net_weight >= 0 AND original_net_weight <= 100000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0008_bill_items ====
-- 0008 bill lines (spec D12, R3 to R7). A line is a snapshot taken at sale time; it never contains the owner-only weight.
-- The database re-checks what R6 and R7 promise: a By Weight line has quantity 1, and item_total = metal + labour + piroi + other charges, to the paisa.

CREATE TABLE IF NOT EXISTS bill_items (
  id UUID NOT NULL,
  bill_id UUID NOT NULL,
  line_no SMALLINT NOT NULL,
  sku_id UUID NOT NULL,
  design_no VARCHAR(64) NOT NULL,
  sku_no VARCHAR(64) NOT NULL,
  category VARCHAR(80) NOT NULL,
  material VARCHAR(10) NOT NULL,
  purity VARCHAR(20) NOT NULL,
  selling_method VARCHAR(16) NOT NULL,
  gross_weight DECIMAL(12,3) NOT NULL,
  customer_net_weight DECIMAL(12,3) NOT NULL,
  quantity INT NOT NULL DEFAULT 1,
  metal_rate DECIMAL(12,2) NOT NULL,
  labour_rate DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  labour_amount DECIMAL(14,2) NOT NULL,
  piroi DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  other_charges DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  metal_amount DECIMAL(14,2) NOT NULL,
  fine_weight_due DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  item_total DECIMAL(14,2) NOT NULL,
  tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  list_metal_rate DECIMAL(12,2) NOT NULL,
  list_labour_rate DECIMAL(12,2) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_bill_items_line (bill_id, line_no),
  UNIQUE KEY uq_bill_items_sku (bill_id, sku_id),
  KEY ix_bill_items_sku (sku_id),
  KEY ix_bill_items_updated (updated_at, id),
  CONSTRAINT fk_bill_items_bill FOREIGN KEY (bill_id) REFERENCES bills (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bill_items_sku FOREIGN KEY (sku_id) REFERENCES skus (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_bill_items_line CHECK (line_no >= 1 AND line_no <= 200),
  CONSTRAINT chk_bill_items_quantity CHECK (quantity >= 1 AND quantity <= 1000),
  CONSTRAINT chk_bill_items_material CHECK (material IN ('Gold', 'Silver')),
  CONSTRAINT chk_bill_items_method CHECK (selling_method IN ('By Weight', 'Per Piece')),
  CONSTRAINT chk_bill_items_by_weight CHECK (selling_method <> 'By Weight' OR quantity = 1),
  CONSTRAINT chk_bill_items_weights CHECK (
    gross_weight >= 0 AND gross_weight <= 100000 AND customer_net_weight >= 0 AND customer_net_weight <= 100000 AND fine_weight_due >= 0 AND fine_weight_due <= 100000
  ),
  CONSTRAINT chk_bill_items_rates CHECK (
    metal_rate >= 0 AND metal_rate <= 100000000 AND labour_rate >= 0 AND labour_rate <= 100000000
    AND list_metal_rate >= 0 AND list_metal_rate <= 100000000 AND (list_labour_rate IS NULL OR (list_labour_rate >= 0 AND list_labour_rate <= 100000000))
  ),
  CONSTRAINT chk_bill_items_amounts CHECK (
    labour_amount >= 0 AND labour_amount <= 1000000000 AND piroi >= 0 AND piroi <= 1000000000 AND other_charges >= 0 AND other_charges <= 1000000000
    AND metal_amount >= 0 AND metal_amount <= 1000000000 AND item_total >= 0 AND item_total <= 1000000000 AND tax_amount >= 0 AND tax_amount <= 1000000000
  ),
  CONSTRAINT chk_bill_items_tax_rate CHECK (tax_rate >= 0 AND tax_rate <= 100),
  CONSTRAINT chk_bill_items_total CHECK (item_total = metal_amount + labour_amount + piroi + other_charges)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0009_receipts ====
-- 0009 receipts and allocations (spec D13, D14, Y1 to Y10). One receipts table: money, silver received, silver settled in cash, money handed back (refund).
-- NOTE: a CHECK that evaluates to NULL PASSES, so every nullable column used in chk_receipts_kind is tested with IS NOT NULL (the first draft let a money receipt without a mode through; found by the tests).
-- There is no 'Credit' mode: an unpaid bill is the absence of a receipt (Y2). The kind decides which other columns must be set (chk_receipts_kind).
-- An allocation can join a receipt and a bill of the SAME customer only: composite foreign keys (Y4).

CREATE TABLE IF NOT EXISTS receipts (
  id UUID NOT NULL,
  customer_id UUID NOT NULL,
  kind VARCHAR(16) NOT NULL,
  mode VARCHAR(16) NULL,
  amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  fine_grams DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  silver_rate DECIMAL(12,2) NULL,
  paid_on DATE NOT NULL,
  reference VARCHAR(120) NULL,
  notes TEXT NULL,
  is_opening TINYINT(1) NOT NULL DEFAULT 0,
  cash_override_reason VARCHAR(500) NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  void_reason VARCHAR(500) NULL,
  voided_at DATETIME(6) NULL,
  voided_by UUID NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  created_by UUID NULL,
  updated_by UUID NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_receipts_id_customer (id, customer_id),
  KEY ix_receipts_customer (customer_id, paid_on),
  KEY ix_receipts_updated (updated_at, id),
  CONSTRAINT fk_receipts_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_receipts_kind CHECK (
    (kind = 'money' AND mode IS NOT NULL AND mode IN ('Cash', 'UPI', 'Card', 'Bank Transfer', 'Other') AND amount > 0 AND fine_grams = 0 AND silver_rate IS NULL)
    OR (kind = 'refund' AND mode IS NOT NULL AND mode IN ('Cash', 'UPI', 'Card', 'Bank Transfer', 'Other') AND amount > 0 AND fine_grams = 0 AND silver_rate IS NULL AND is_opening = 0)
    OR (kind = 'fine_cash' AND mode = 'Cash' AND amount > 0 AND fine_grams > 0 AND silver_rate IS NOT NULL AND silver_rate > 0 AND is_opening = 0)
    OR (kind = 'fine_silver' AND mode IS NULL AND amount = 0 AND fine_grams > 0 AND silver_rate IS NULL)
  ),
  CONSTRAINT chk_receipts_opening CHECK (is_opening IN (0, 1) AND (is_opening = 0 OR (kind = 'money' AND mode = 'Other') OR kind = 'fine_silver')),
  CONSTRAINT chk_receipts_caps CHECK (amount <= 1000000000 AND fine_grams <= 100000 AND (silver_rate IS NULL OR silver_rate <= 100000000)),
  CONSTRAINT chk_receipts_status CHECK (status IN ('active', 'voided')),
  CONSTRAINT chk_receipts_void CHECK (
    ((status = 'voided') = (void_reason IS NOT NULL)) AND ((status = 'voided') = (voided_at IS NOT NULL)) AND ((status = 'voided') = (voided_by IS NOT NULL))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS receipt_allocations (
  id UUID NOT NULL,
  receipt_id UUID NOT NULL,
  bill_id UUID NOT NULL,
  customer_id UUID NOT NULL,
  amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  fine_grams DECIMAL(12,3) NOT NULL DEFAULT 0.000,
  released_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_allocations_receipt (receipt_id, customer_id),
  KEY ix_allocations_bill (bill_id, customer_id),
  KEY ix_allocations_updated (updated_at, id),
  CONSTRAINT fk_allocations_receipt FOREIGN KEY (receipt_id, customer_id) REFERENCES receipts (id, customer_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_allocations_bill FOREIGN KEY (bill_id, customer_id) REFERENCES bills (id, customer_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_allocations_one_kind CHECK (amount >= 0 AND fine_grams >= 0 AND (amount > 0 OR fine_grams > 0) AND (amount = 0 OR fine_grams = 0)),
  CONSTRAINT chk_allocations_caps CHECK (amount <= 1000000000 AND fine_grams <= 100000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0010_audit_checks ====
-- 0010 audit log, nightly checks, backup log (spec draft 4: D16, D17, L1, L2, I8, B2).
-- NODE-DESIGN D-Q2: the API writes the audit rows in the same transaction as the change (no trigger needed). db/optional/0900 makes audit_log append-only
-- if Hostinger's user may create triggers. check_runs and backup_runs are readable by the owner only (an API rule).
-- audit_log.action 'event' is for a login, a failed login, a password change, an admin-door call or a job run (facts in new_row); actor_role is free text (a role, import, admin-cli, job, sql).
-- backup_runs.kind: db_dump (the export, WITHOUT photo bytes), photo_copy (the once-only copy of each photo, NODE-DESIGN D-Q11), restore_drill.

CREATE TABLE IF NOT EXISTS audit_log (
  id BIGINT NOT NULL AUTO_INCREMENT,
  at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  actor UUID NULL,
  actor_role VARCHAR(20) NULL,
  request_id UUID NULL,
  table_name VARCHAR(64) NOT NULL,
  row_id VARCHAR(64) NOT NULL,
  action VARCHAR(10) NOT NULL,
  old_row JSON NULL,
  new_row JSON NULL,
  PRIMARY KEY (id),
  KEY ix_audit_row (table_name, row_id),
  KEY ix_audit_at (at),
  CONSTRAINT chk_audit_action CHECK (action IN ('insert', 'update', 'event'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS check_runs (
  id BIGINT NOT NULL AUTO_INCREMENT,
  ran_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  ok TINYINT(1) NOT NULL,
  details JSON NULL,
  PRIMARY KEY (id),
  KEY ix_check_runs_at (ran_at),
  CONSTRAINT chk_check_runs_ok CHECK (ok IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS backup_runs (
  id BIGINT NOT NULL AUTO_INCREMENT,
  ran_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  kind VARCHAR(16) NOT NULL,
  ok TINYINT(1) NOT NULL,
  bytes BIGINT NOT NULL DEFAULT 0,
  detail JSON NULL,
  PRIMARY KEY (id),
  KEY ix_backup_runs_at (ran_at),
  CONSTRAINT chk_backup_runs_kind CHECK (kind IN ('db_dump', 'photo_copy', 'restore_drill')),
  CONSTRAINT chk_backup_runs_values CHECK (ok IN (0, 1) AND bytes >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==== 0011_views ====
-- 0011 the four derived views of spec section 11 (V1 bill_summary, V2 customer_balances, V3 customer_ledger, V4 daily_totals). Nothing in them is stored (S3).
-- All are SQL SECURITY INVOKER: the caller's own rights apply and no definer account is involved (an application user can create them).
-- CREATE OR REPLACE makes this file safe to run again (MariaDB DDL is not transactional, so a half-applied migration must be repeatable).
--
-- A LIVE allocation is a receipt_allocations row whose released_at is NULL AND whose receipt is 'active'. A voided receipt's allocation never counts, released or not.
-- Business dates are Indian: a cancel or a void is dated the day it happened in Asia/Kolkata (+05:30, no time-zone tables on the plan, so CONVERT_TZ gets the offset).
-- Money sums are DECIMAL(18,2) and silver sums DECIMAL(16,3): wider than the columns so a sum can never overflow.

-- V1. One row per bill. A cancelled bill shows 0 received, 0 pending, 0 fine settled and 0 fine pending (K3 released its allocations).
CREATE OR REPLACE SQL SECURITY INVOKER VIEW bill_summary AS
SELECT
  b.id AS id,
  b.bill_no AS bill_no,
  b.customer_id AS customer_id,
  b.bill_date AS bill_date,
  b.doc_type AS doc_type,
  b.sale_type AS sale_type,
  b.status AS status,
  b.reissue_of AS reissue_of,
  b.grand_total AS grand_total,
  CAST(IF(b.status = 'active', COALESCE(a.received, 0), 0) AS DECIMAL(18,2)) AS received,
  CAST(IF(b.status = 'active', b.grand_total - COALESCE(a.received, 0), 0) AS DECIMAL(18,2)) AS pending,
  b.fine_weight_due AS fine_due,
  CAST(IF(b.status = 'active', COALESCE(a.fine_settled, 0), 0) AS DECIMAL(16,3)) AS fine_settled,
  CAST(IF(b.status = 'active', b.fine_weight_due - COALESCE(a.fine_settled, 0), 0) AS DECIMAL(16,3)) AS fine_pending,
  CASE
    WHEN b.status <> 'active' THEN 'Cancelled'
    WHEN b.grand_total - COALESCE(a.received, 0) = 0 AND b.fine_weight_due - COALESCE(a.fine_settled, 0) = 0 THEN 'Paid'
    WHEN COALESCE(a.received, 0) > 0 OR COALESCE(a.fine_settled, 0) > 0 THEN 'Partial'
    ELSE 'Pending'
  END AS payment_status,
  COALESCE(i.item_count, 0) AS item_count,
  b.created_at AS created_at,
  b.updated_at AS updated_at
FROM bills b
LEFT JOIN (
  SELECT al.bill_id AS bill_id, SUM(al.amount) AS received, SUM(al.fine_grams) AS fine_settled
  FROM receipt_allocations al
  JOIN receipts r ON r.id = al.receipt_id
  WHERE al.released_at IS NULL AND r.status = 'active'
  GROUP BY al.bill_id
) a ON a.bill_id = b.id
LEFT JOIN (
  SELECT bill_id, COUNT(*) AS item_count FROM bill_items GROUP BY bill_id
) i ON i.bill_id = b.id;

-- V2. One row per customer (the walk-in too), keyed by the customer's id.
-- balance comes from totals (billed - received + refunded); outstanding and advance come from allocations. The two routes must agree (I4, I10).
CREATE OR REPLACE SQL SECURITY INVOKER VIEW customer_balances AS
SELECT
  cu.id AS id,
  CAST(COALESCE(b.billed, 0) AS DECIMAL(18,2)) AS billed,
  CAST(COALESCE(b.total_purchases, 0) AS DECIMAL(18,2)) AS total_purchases,
  CAST(COALESCE(r.received, 0) AS DECIMAL(18,2)) AS received,
  CAST(COALESCE(r.refunded, 0) AS DECIMAL(18,2)) AS refunded,
  CAST(COALESCE(a.allocated, 0) AS DECIMAL(18,2)) AS allocated,
  CAST(COALESCE(b.billed, 0) - COALESCE(a.allocated, 0) AS DECIMAL(18,2)) AS outstanding,
  CAST(COALESCE(r.received, 0) - COALESCE(a.allocated, 0) - COALESCE(r.refunded, 0) AS DECIMAL(18,2)) AS advance,
  CAST(COALESCE(b.billed, 0) - COALESCE(r.received, 0) + COALESCE(r.refunded, 0) AS DECIMAL(18,2)) AS balance,
  CAST(COALESCE(b.fine_billed, 0) AS DECIMAL(16,3)) AS fine_billed,
  CAST(COALESCE(r.fine_received, 0) AS DECIMAL(16,3)) AS fine_received,
  CAST(COALESCE(a.fine_allocated, 0) AS DECIMAL(16,3)) AS fine_allocated,
  CAST(COALESCE(b.fine_billed, 0) - COALESCE(a.fine_allocated, 0) AS DECIMAL(16,3)) AS fine_outstanding,
  CAST(COALESCE(r.fine_received, 0) - COALESCE(a.fine_allocated, 0) AS DECIMAL(16,3)) AS fine_advance,
  CAST(COALESCE(b.fine_billed, 0) - COALESCE(r.fine_received, 0) AS DECIMAL(16,3)) AS fine_balance,
  b.last_purchase AS last_purchase,
  cu.updated_at AS updated_at
FROM customers cu
LEFT JOIN (
  SELECT customer_id,
         SUM(grand_total) AS billed,
         SUM(IF(doc_type <> 'opening_balance', grand_total, 0)) AS total_purchases,
         SUM(fine_weight_due) AS fine_billed,
         MAX(IF(doc_type <> 'opening_balance', bill_date, NULL)) AS last_purchase
  FROM bills
  WHERE status = 'active'
  GROUP BY customer_id
) b ON b.customer_id = cu.id
LEFT JOIN (
  SELECT customer_id,
         SUM(IF(kind = 'money', amount, 0)) AS received,
         SUM(IF(kind = 'refund', amount, 0)) AS refunded,
         SUM(IF(kind IN ('fine_silver', 'fine_cash'), fine_grams, 0)) AS fine_received
  FROM receipts
  WHERE status = 'active'
  GROUP BY customer_id
) r ON r.customer_id = cu.id
LEFT JOIN (
  SELECT al.customer_id AS customer_id, SUM(al.amount) AS allocated, SUM(al.fine_grams) AS fine_allocated
  FROM receipt_allocations al
  JOIN receipts rr ON rr.id = al.receipt_id
  WHERE al.released_at IS NULL AND rr.status = 'active'
  GROUP BY al.customer_id
) a ON a.customer_id = cu.id;

-- V3. One row per event of a customer with a running balance (debit minus credit) in the order key (entry_date, entry_at, kind_rank, id).
-- The sums are partitioned by customer_id, so a filter on one customer is applied before the sums.
-- kind_rank: Invoice and Opening 1, Cancellation 2, Payment, Opening advance and Fine 3, Refund 4, Void 5.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW customer_ledger AS
SELECT
  e.customer_id AS customer_id,
  e.entry_date AS entry_date,
  e.entry_at AS entry_at,
  e.kind_rank AS kind_rank,
  e.id AS id,
  e.kind AS kind,
  e.description AS description,
  e.debit AS debit,
  e.credit AS credit,
  e.fine_debit AS fine_debit,
  e.fine_credit AS fine_credit,
  CAST(SUM(e.debit - e.credit) OVER (PARTITION BY e.customer_id ORDER BY e.entry_date, e.entry_at, e.kind_rank, e.id ROWS UNBOUNDED PRECEDING) AS DECIMAL(18,2)) AS balance,
  CAST(SUM(e.fine_debit - e.fine_credit) OVER (PARTITION BY e.customer_id ORDER BY e.entry_date, e.entry_at, e.kind_rank, e.id ROWS UNBOUNDED PRECEDING) AS DECIMAL(16,3)) AS fine_balance
FROM (
  SELECT customer_id, bill_date AS entry_date, created_at AS entry_at, 1 AS kind_rank, id,
         IF(doc_type = 'opening_balance', 'Opening', 'Invoice') AS kind,
         CONCAT(IF(doc_type = 'opening_balance', 'Opening balance ', 'Invoice '), bill_no) AS description,
         CAST(grand_total AS DECIMAL(18,2)) AS debit, CAST(0 AS DECIMAL(18,2)) AS credit,
         CAST(fine_weight_due AS DECIMAL(16,3)) AS fine_debit, CAST(0 AS DECIMAL(16,3)) AS fine_credit
  FROM bills
  UNION ALL
  SELECT customer_id, DATE(CONVERT_TZ(cancelled_at, '+00:00', '+05:30')), cancelled_at, 2, id,
         'Cancellation', CONCAT('Cancelled ', bill_no),
         CAST(0 AS DECIMAL(18,2)), CAST(grand_total AS DECIMAL(18,2)),
         CAST(0 AS DECIMAL(16,3)), CAST(fine_weight_due AS DECIMAL(16,3))
  FROM bills
  WHERE status = 'cancelled'
  UNION ALL
  SELECT customer_id, paid_on, created_at, IF(kind = 'refund', 4, 3), id,
         CASE kind WHEN 'money' THEN IF(is_opening = 1, 'Opening advance', 'Payment') WHEN 'refund' THEN 'Refund' ELSE 'Fine' END,
         CASE kind
           WHEN 'money' THEN CONCAT(IF(is_opening = 1, 'Opening advance', 'Payment'), ' (', mode, ')')
           WHEN 'refund' THEN CONCAT('Refund (', mode, ')')
           WHEN 'fine_cash' THEN CONCAT('Silver ', fine_grams, ' g settled in cash at rate ', silver_rate, ' = ', amount)
           ELSE CONCAT('Silver received ', fine_grams, ' g')
         END,
         CAST(IF(kind = 'refund', amount, 0) AS DECIMAL(18,2)),
         CAST(IF(kind = 'money', amount, 0) AS DECIMAL(18,2)),
         CAST(0 AS DECIMAL(16,3)),
         CAST(IF(kind IN ('fine_silver', 'fine_cash'), fine_grams, 0) AS DECIMAL(16,3))
  FROM receipts
  UNION ALL
  SELECT customer_id, DATE(CONVERT_TZ(voided_at, '+00:00', '+05:30')), voided_at, 5, id,
         'Void',
         CONCAT('Void of ', CASE kind WHEN 'money' THEN IF(is_opening = 1, 'opening advance', 'payment') WHEN 'refund' THEN 'refund' WHEN 'fine_cash' THEN 'silver settled in cash' ELSE 'silver received' END),
         CAST(IF(kind = 'money', amount, 0) AS DECIMAL(18,2)),
         CAST(IF(kind = 'refund', amount, 0) AS DECIMAL(18,2)),
         CAST(IF(kind IN ('fine_silver', 'fine_cash'), fine_grams, 0) AS DECIMAL(16,3)),
         CAST(0 AS DECIMAL(16,3))
  FROM receipts
  WHERE status = 'voided'
) e;

-- V4. The cash book: one row per (business_date, mode). Money and silver settled in cash come in on paid_on, a refund goes out on paid_on,
-- a void reverses on the Indian day of the void. Opening advances (is_opening) were never counted, so their void adds nothing either.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW daily_totals AS
SELECT
  t.business_date AS business_date,
  t.mode AS mode,
  CAST(SUM(t.money_in) AS DECIMAL(18,2)) AS money_in,
  CAST(SUM(t.money_out) AS DECIMAL(18,2)) AS money_out,
  CAST(SUM(t.money_in) - SUM(t.money_out) AS DECIMAL(18,2)) AS net
FROM (
  SELECT paid_on AS business_date, mode,
         CAST(IF(kind IN ('money', 'fine_cash'), amount, 0) AS DECIMAL(18,2)) AS money_in,
         CAST(IF(kind = 'refund', amount, 0) AS DECIMAL(18,2)) AS money_out
  FROM receipts
  WHERE is_opening = 0 AND kind IN ('money', 'fine_cash', 'refund')
  UNION ALL
  SELECT DATE(CONVERT_TZ(voided_at, '+00:00', '+05:30')), mode,
         CAST(IF(kind = 'refund', amount, 0) AS DECIMAL(18,2)),
         CAST(IF(kind IN ('money', 'fine_cash'), amount, 0) AS DECIMAL(18,2))
  FROM receipts
  WHERE status = 'voided' AND is_opening = 0 AND kind IN ('money', 'fine_cash', 'refund')
) t
GROUP BY t.business_date, t.mode;
